        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    amount = 0.0
    for el, x in (s.get('composition') or {}).items():
        if x is None or x <= 0:
            continue
        r = (props.get(el) or {}).get('covalent_radius_A')
        if r is None or r <= 0:
