def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    coordination = [0.0 for a in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= n or j >= n or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0:
            continue
        coordination[i] += occ[j] * max(0.0, 1.35 - d / (radii[i] + radii[j])) ** 2
    amount = sum(occ[i] for i in range(n) if radii[i] > 0)
    if amount <= 0:
        return 0.0
    mean = sum(occ[i] * coordination[i] for i in range(n) if radii[i] > 0) / amount
    if mean <= 0:
        return 0.0
    variance = sum(occ[i] * (coordination[i] - mean) ** 2 for i in range(n) if radii[i] > 0) / amount
    return float(variance ** 0.5 / mean)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    first = [0.0 for a in sites]
    second = [0.0 for a in sites]
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= n or j >= n or d <= 0:
            continue
        if occ[i] <= 0 or occ[j] <= 0:
            continue
        if first[i] <= 0 or d < first[i]:
            second[i] = first[i]
            first[i] = d
        elif second[i] <= 0 or d < second[i]:
            second[i] = d
    total = 0.0
    amount = 0.0
    for i in range(n):
        if first[i] > 0 and second[i] > 0 and occ[i] > 0:
            total += occ[i] * max(0.0, second[i] / first[i] - 1.0)
            amount += occ[i]
    return float(total / amount) if amount > 0 else 0.0

